WITH unpacked AS (SELECT id, service, host, level, status_code, payload_json, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs WHERE status_code BETWEEN 269 AND 281) SELECT *, ROW_NUMBER() OVER w_hist seq_no, SUM(retry_count) OVER w_grp running_retry_count FROM unpacked WINDOW w_hist AS (ORDER BY retry_count, id), w_grp AS (PARTITION BY service, level ORDER BY status_code, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
